import {BgAssetManager} from "../shared";
import {addButtonInteractivity, testButtonViewInteractivity} from '../auto_generated/utils/addButtonViewInteractivity';
import {addGeneratedButtonSounds} from '../auto_tuned/utils.tuned';
import {getCurrentLocale} from '../../assets';
import {forEach2D, getCanvasSize, grid, map2D, ParticleEffectLayer, setSceneLocale} from '../../common';
import {makeAlign} from '@kvisaz/phaser-sugar';
import {makeView} from '../../common/gameObjects/makeView/makeView';

export class ViewTestScene extends Phaser.Scene {
    constructor() {
        super('ViewTestScene');
    }

    preload() {
    }

    create() {
        const scene = this;
        setSceneLocale(scene, getCurrentLocale());
        addButtonInteractivity(scene);
        addGeneratedButtonSounds(scene);
        testButtonViewInteractivity(scene);
        new BgAssetManager({scene, isColorOverlay: true});
        // new SoundPlayerFeature({scene, gameConfig});
        new ParticleEffectLayer({scene});
        this.createTestViews(this);
    }

    private createTestViews(scene: Phaser.Scene) {
        console.log('createTestViews start');
        this.createSceneBorder(scene);
        this.createSampleTextGrid(scene);

    }

    private createSceneBorder(scene: Phaser.Scene) {
        const canvasSize = getCanvasSize(scene);
        const sceneBorderLine = new Phaser.GameObjects.Rectangle(scene, 0, 0, canvasSize.width, canvasSize.height);
        sceneBorderLine.setStrokeStyle(2, 0x22ff22);
        makeAlign(align => {
            align.anchorSceneScreen(scene).center(sceneBorderLine);
        });
        scene.add.existing(sceneBorderLine);
    }

    private createSampleTextGrid(scene: Phaser.Scene) {
        const sampleTextGrid = makeView(scene, b => {
            const texts = [
                [1, 2, 3, 4],
                [5, 6, 7, 8],
            ];
            const textObjects = map2D(texts, (value, col, row) => b.text(
                {text: value, style: {fontSize: '36px', color: '#dedede'}}));
            grid(textObjects, {type: 'yx'});
            return b.con(textObjects.flat());
        });
        makeAlign(align => {
            align.anchorSceneScreen(scene).center(sampleTextGrid);
        });
    }
}
