type WindowMessageKey<TypedMessages extends object> = Extract<keyof TypedMessages, string>;

type WindowMessageEnvelope<
  TypedMessages extends object,
  K extends WindowMessageKey<TypedMessages> = WindowMessageKey<TypedMessages>,
> = {
  type: K;
  payload: TypedMessages[K];
};

type WindowMessageCallback<TypedMessages extends object, K extends WindowMessageKey<TypedMessages>> = (
  payload: TypedMessages[K],
  event: MessageEvent<WindowMessageEnvelope<TypedMessages, K>>,
) => void;

type WindowMessageOnceCallback<TypedMessages extends object, K extends WindowMessageKey<TypedMessages>> = (
  payload: TypedMessages[K] | undefined,
  event?: MessageEvent<WindowMessageEnvelope<TypedMessages, K>>,
) => void;

interface ISafeWindowMessagesAdapterProps {
  target?: Window;
  allowedOrigins?: readonly string[];
  source?: MessageEventSource | null;
}

/**
 * Типизированный адаптер для `window.postMessage`, который снимает только свои подписки.
 *
 * @example
 * ```ts
 * type AppWindowMessages = {
 *   gamePause: { reason: string };
 *   gameResume: undefined;
 * };
 *
 * const messages = new SafeWindowMessagesAdapter<AppWindowMessages>({
 *   allowedOrigins: [window.location.origin],
 * });
 *
 * const unSubPause = messages.on("gamePause", ({ reason }) => {
 *   console.log(reason);
 * });
 *
 * messages.post(window, "gameResume", undefined, window.location.origin);
 *
 * unSubPause();
 * messages.unSubscribeAll();
 * ```
 */
export class SafeWindowMessagesAdapter<TypedMessages extends object> {
  private readonly target: Window;
  private readonly unSubs = new Set<() => void>();

  /** Создает adapter для указанного window target или текущего `window`. */
  constructor(private readonly props: ISafeWindowMessagesAdapterProps = {}) {
    this.target = props.target ?? window;
  }

  /**
   * Подписывается на сообщение с конкретным `type` и возвращает ручную отписку.
   */
  on<K extends WindowMessageKey<TypedMessages>>(
    messageType: K,
    callback: WindowMessageCallback<TypedMessages, K>,
  ): () => void {
    const handler = (event: MessageEvent<unknown>) => {
      if (!this.isAllowedEvent(event) || !this.isMessageEnvelope(event.data, messageType)) {
        return;
      }

      try {
        callback(event.data.payload, event as MessageEvent<WindowMessageEnvelope<TypedMessages, K>>);
      } catch (error) {
        console.error("SafeWindowMessagesAdapter listener error", error);
      }
    };

    this.target.addEventListener("message", handler);
    return this.trackUnSub(() => this.target.removeEventListener("message", handler));
  }

  /**
   * Подписывается на одно сообщение и снимает listener после первого срабатывания.
   */
  once<K extends WindowMessageKey<TypedMessages>>(
    messageType: K,
    callback: WindowMessageOnceCallback<TypedMessages, K>,
    timeout?: number,
  ): () => void {
    let timeoutId: number | undefined;
    let unSub = () => {};
    const handler = (event: MessageEvent<unknown>) => {
      if (!this.isAllowedEvent(event) || !this.isMessageEnvelope(event.data, messageType)) {
        return;
      }

      unSub();
      try {
        callback(event.data.payload, event as MessageEvent<WindowMessageEnvelope<TypedMessages, K>>);
      } catch (error) {
        console.error("SafeWindowMessagesAdapter once listener error", error);
      }
    };

    this.target.addEventListener("message", handler);
    unSub = this.trackUnSub(() => {
      this.target.removeEventListener("message", handler);
      if (timeoutId != null) {
        clearTimeout(timeoutId);
      }
    });

    if (timeout != null) {
      timeoutId = window.setTimeout(() => {
        unSub();
        try {
          callback(undefined);
        } catch (error) {
          console.error("SafeWindowMessagesAdapter once timeout listener error", error);
        }
      }, timeout);
    }

    return unSub;
  }

  /**
   * Ждет одно сообщение и отменяет ожидание при `unSubscribeAll`.
   */
  wait<K extends WindowMessageKey<TypedMessages>>(messageType: K): Promise<TypedMessages[K]> {
    return new Promise((resolve, reject) => {
      let settled = false;
      let tracked: (() => void) | undefined;
      const baseUnSub = this.on(messageType, (payload) => {
        if (settled) return;
        settled = true;
        tracked?.();
        resolve(payload);
      });

      tracked = this.trackUnSub(() => {
        if (!settled) {
          settled = true;
          reject(new Error(`SafeWindowMessagesAdapter: disposed before message "${messageType}" received`));
        }
        baseUnSub();
      });
    });
  }

  /**
   * Отправляет типизированное сообщение в указанный window target.
   */
  post<K extends WindowMessageKey<TypedMessages>>(
    target: Window,
    messageType: K,
    payload: TypedMessages[K],
    targetOrigin = "*",
  ): void {
    target.postMessage({
      type: messageType,
      payload,
    } as WindowMessageEnvelope<TypedMessages, K>, targetOrigin);
  }

  /**
   * Снимает только listeners, созданные этим adapter-экземпляром.
   */
  unSubscribeAll(): void {
    Array.from(this.unSubs).forEach((unSub) => unSub());
    this.unSubs.clear();
  }

  /**
   * Оборачивает отписку так, чтобы повторный вызов был безопасным.
   */
  private trackUnSub(unSub: () => void): () => void {
    const tracked = () => {
      if (!this.unSubs.has(tracked)) return;
      this.unSubs.delete(tracked);
      unSub();
    };
    this.unSubs.add(tracked);
    return tracked;
  }

  /**
   * Проверяет источник сообщения, если adapter создан с ограничениями.
   */
  private isAllowedEvent(event: MessageEvent<unknown>): boolean {
    const {allowedOrigins, source} = this.props;
    if (allowedOrigins != null && !allowedOrigins.includes(event.origin)) {
      return false;
    }
    if (source !== undefined && event.source !== source) {
      return false;
    }
    return true;
  }

  /**
   * Проверяет минимальный runtime-контракт сообщения без валидации payload.
   */
  private isMessageEnvelope<K extends WindowMessageKey<TypedMessages>>(
    data: unknown,
    messageType: K,
  ): data is WindowMessageEnvelope<TypedMessages, K> {
    return typeof data === "object"
      && data != null
      && "type" in data
      && (data as { type?: unknown }).type === messageType
      && "payload" in data;
  }
}
