import {GamePlayCardTheme, GamePlayerData} from "./logic";
import {getUrlParam, isAllowedHost} from "./common";

/** Возвращает стартовые playerData с учетом разрешенных URL-читов. */
export function getDefaultPlayerData(): GamePlayerData {
  return {
    consumableUndo: 0,
    consumableMagic: 0,
    consumableHint: 0,
    isSoundOn: true,
    isMusicOn: true,
    locale: "en",
    spiderSuitsMode: 1,
    cardsTheme: GamePlayCardTheme.chibi,
    gameBgUrlOverlayOpacity: 0.5,
    ...getCheatPlayerData(),
  };
}

/** Возвращает patch playerData из URL-читов только на разрешенных хостах. */
function getCheatPlayerData(): Partial<GamePlayerData> | undefined {
  if (!isAllowedHost(["localhost", "kvisaz.github.io"])) return;

  return mergeCheatData([
    getMegaBonusData("iddqd"),
    getZeroBonusData("zero"),
  ]);
}

/** Выдает большой пакет расходников через URL-параметр. */
function getMegaBonusData(cheat: string): Partial<GamePlayerData> | undefined {
  const isCheatEnabled = getUrlParam(cheat);

  if (!isCheatEnabled) return;

  return {
    consumableUndo: 999,
    consumableHint: 999,
    consumableMagic: 999,
  };
}

/** Обнуляет расходники через URL-параметр. */
function getZeroBonusData(cheat: string): Partial<GamePlayerData> | undefined {
  const isCheatEnabled = getUrlParam(cheat);

  if (!isCheatEnabled) return;

  return {
    consumableUndo: 0,
    consumableHint: 0,
    consumableMagic: 0,
  };
}

/** Объединяет включенные URL-чити в один patch. */
function mergeCheatData(
  items: Array<Partial<GamePlayerData> | undefined>,
): Partial<GamePlayerData> | undefined {
  let hasCheat = false;
  const result: Partial<GamePlayerData> = {};

  items.forEach((item) => {
    if (item == null) return;
    hasCheat = true;
    Object.assign(result, item);
  });

  return hasCheat ? result : undefined;
}
