import {getPlayerConsumables, makePlayerConsumablesPatch} from "../playerDataConsumables";
import type {GamePlayerData, IShopConfig} from "../types";
import {ConsumableType} from "./types";
import {getShopItemData, isShopItemId} from "./getShopItemData";

export interface IAddShopItemToStateProps {
  shopConfig: IShopConfig;
  shopItemId: string;
  prevPlayerData: GamePlayerData;
}

export type AddShopItemToState = (props: IAddShopItemToStateProps) => GamePlayerData;

/** Конвертирует id покупки в новый баланс расходных бонусов игрока. */
export function addShopItemToState(props: IAddShopItemToStateProps): GamePlayerData {
  const {shopConfig, shopItemId, prevPlayerData} = props;
  if (!isShopItemId(shopConfig, shopItemId)) {
    throw new Error(`unknown shop item id: ${shopItemId}`);
  }

  const {consumables} = getShopItemData(shopConfig, shopItemId);
  const current = getPlayerConsumables(prevPlayerData);

  return {
    ...prevPlayerData,
    ...makePlayerConsumablesPatch({
      [ConsumableType.UNDO]: current[ConsumableType.UNDO] + consumables[ConsumableType.UNDO],
      [ConsumableType.HINT]: current[ConsumableType.HINT] + consumables[ConsumableType.HINT],
      [ConsumableType.MAGIC]: current[ConsumableType.MAGIC] + consumables[ConsumableType.MAGIC],
    }),
  };
}
