import { Purchase, SDK } from "ysdk";
import { getErrorMessage, getSafeNumber } from "../../common";
import {
  InAppApiService,
  InAppPurchaseActivationHandler,
  ShopPurchaseResult,
  ShopServiceState,
  YandexApiShopItemDto,
} from "./types";

interface IShopServiceProps {
  sdk: SDK;
}

/**
 *  Этот сервис привязан к Яндекс Сервису
 *  - поэтому надо менять нейминг
 **/
export class YandexInAppService implements InAppApiService {
  private state: ShopServiceState = {};

  constructor(private readonly props: IShopServiceProps) {}

  /**
   * подключаем API
   * - читаем каталог покупок без скрытой активации pending-покупок
   * **/
  async preload(): Promise<void> {
    try {
      const payments = await this.props.sdk.getPayments();
      if (payments == null) return;
      this.state.payments = payments;
      this.state.products = await payments.getCatalog();
    } catch (e) {
      console.warn(e);
    }
  }

  /** Здесь логика Яндекса смешивается с логикой конкретной игры
   *  todo надо чтобы он просто возвращал массив доступных ID или еще лучше Set
   * **/
  getShopData(): Set<YandexApiShopItemDto> | undefined {
    const products = this.state.products;
    if (products == null) return;
    const set = new Set<YandexApiShopItemDto>();
    for (const product of products) {
      set.add({
        id: product.id,
        price: getSafeNumber(product.priceValue),
        currency: product.priceCurrencyCode,
      });
    }
    return set;
  }

  /**
   * Покупает consumable и активирует его перед consumePurchase.
   * **/
  async shopPurchase(
    purchaseId: string,
    activatePurchase: InAppPurchaseActivationHandler,
  ): Promise<ShopPurchaseResult> {
    const payments = this.state.payments;
    if (payments == null) {
      return { error: "payments not available" };
    }

    let purchase: Purchase;
    try {
      purchase = await payments.purchase({ id: purchaseId });
    } catch (e) {
      return { error: getErrorMessage(e) };
    }

    try {
      await activatePurchase(purchase);
    } catch (e) {
      return { error: getErrorMessage(e) };
    }

    try {
      await payments.consumePurchase(purchase.purchaseToken);
    } catch (e) {
      return { error: getErrorMessage(e) };
    }

    return { purchaseId };
  }

  /** Активирует необработанные покупки явным handler-ом игрового баланса. */
  async activatePendingPurchases(activatePurchase: InAppPurchaseActivationHandler): Promise<void> {
    const payments = this.state.payments;
    if (payments == null) return;

    try {
      const purchases = await payments.getPurchases();
      for (const purchase of purchases) {
        await this.activatePurchase(purchase, activatePurchase);
      }
    } catch (e) {
      console.warn(e);
    }
  }

  /** Активирует pending-покупку и consume-ит ее только после успешной игровой транзакции. */
  private async activatePurchase(
    purchase: Purchase,
    activatePurchase: InAppPurchaseActivationHandler,
  ): Promise<void> {
    const payments = this.state.payments;
    if (payments == null) return;

    /** Сначала записываем награду в баланс и дожидаемся сохранения, затем закрываем покупку в API. */
    try {
      await activatePurchase(purchase);
    } catch (e) {
      console.warn(e);
      return;
    }

    /** отмечаем у API что купили **/
    try {
      await payments.consumePurchase(purchase.purchaseToken);
    } catch (e) {
      console.warn(e);
    }
  }
}
