import type {ConsumableAmounts} from "./shop/types";
import {ConsumableType} from "./shop/types";
import {GamePlayerData} from "./types";

export function getPlayerConsumables(playerData: GamePlayerData): ConsumableAmounts {
    return {
        [ConsumableType.UNDO]: playerData.consumableUndo,
        [ConsumableType.HINT]: playerData.consumableHint,
        [ConsumableType.MAGIC]: playerData.consumableMagic,
    };
}

export function makePlayerConsumablesPatch(
    consumables: ConsumableAmounts,
): Pick<GamePlayerData, "consumableUndo" | "consumableHint" | "consumableMagic"> {
    /** Мост между доменной моделью бонусов и плоским форматом сохранения. **/
    return {
        consumableUndo: consumables[ConsumableType.UNDO],
        consumableHint: consumables[ConsumableType.HINT],
        consumableMagic: consumables[ConsumableType.MAGIC],
    };
}
