import {SDK} from "ysdk";
import {getErrorMessage} from "../../common";
import {
    getShopItemData,
    isInAppPurchaseId,
    isRewardPurchaseId
} from "../../logic";
import type {AddShopItemToState, GamePlayerData, IShopConfig, IShopItemData} from "../../logic";
import {
    AbstractPlayerDataService,
    BonusShopBuyViewData,
    BonusShopViewData,
    IInAppPurchase,
    InAppApiService,
    ShopPurchaseKind,
    ShopPurchaseResult
} from "./types";
import {isMockShopEnabled} from "../GameService/mockGetters";
import {MockInAppService} from "./MockInAppService";
import {YandexInAppService} from "./YandexInAppService";
import {
    ISimpleApiShopItem,
    RewardAdResult
} from '../../logic/shop_simple';

interface IProps {
    /** Необходимо для тестов **/
    isMockShop?: boolean;
    /** Необходимо для API **/
    sdk?: SDK;
    /** Необходимо для показа рекламы **/
    showRewardedAd: () => Promise<RewardAdResult>;
    /** Необходимо для зачисления **/
    playerDataService: AbstractPlayerDataService;
    /** Проверяет, можно ли сейчас показывать reward-рекламу. **/
    isRewardAdEnable: () => boolean;

    /** Полный конфиг магазина, доступный только сервисному слою. */
    shopConfig: IShopConfig;
    /** Преобразует товар магазина в изменение баланса игрока. */
    addShopItemToState: AddShopItemToState;
}

/**
 *  Простейший сервис который
 * - получает простой список предметов из API
 * - зачисляет на баланс
 * - НЕ создает каталог предметов для отображения - это делает UI
 * **/
export class SimpleShopService {
    private _apiShopItems: ISimpleApiShopItem[];
    private apiService?: InAppApiService;

    constructor(private props: IProps) {
        this._apiShopItems = [];
    }

    /** Возвращает товары, которые реально пришли из API in-app покупок. */
    get apiShopItems(): ISimpleApiShopItem[] {
        return this._apiShopItems;
    }

    /** Ищет API-товар по id без доступа UI к исходному списку конфига. */
    getApiShopItemById(id: string): ISimpleApiShopItem | undefined {
        return this.apiShopItems.find(item => item.id === id);
    }

    /** Загружает внешний магазин и сохраняет доступные API-товары. */
    async preload(): Promise<void> {
        try {
            await this.initApi();
            /** Если подключили API магазина
             * - проверяем какие покупки доступны, проставляем цены **/
            this.apiService?.getShopData()?.forEach(apiItem => {
                this._apiShopItems.push(apiItem);
            })
        } catch (e) {
            console.warn(e);
        }
    }

    /** проверка покупных **/
    isShopItemsEnabled(): boolean {
        return this.apiShopItems.length > 0;
    }

    /** проверка награждаемых **/
    isRewardEnabled(): boolean {
        return this.props.isRewardAdEnable()
    }

    /** Возвращает первый reward id магазина бонусов. */
    getRewardPurchaseId(): string | undefined {
        return this.props.shopConfig.shopItemsOrdered.rewardItemIds[0];
    }

    /** Проверяет id rewarded-награды по внутреннему конфигу магазина. */
    isRewardPurchaseId(value: unknown): boolean {
        return isRewardPurchaseId(this.props.shopConfig, value);
    }

    /** Проверяет id in-app покупки по внутреннему конфигу магазина. */
    isInAppPurchaseId(value: unknown): boolean {
        return isInAppPurchaseId(this.props.shopConfig, value);
    }

    /** Возвращает тип покупки по id или undefined для неизвестного id. */
    getPurchaseKind(id: unknown): ShopPurchaseKind | undefined {
        if (this.isRewardPurchaseId(id)) {
            return "reward";
        }

        return this.isInAppPurchaseId(id) ? "inApp" : undefined;
    }

    /** Возвращает начисляемые данные товара без раскрытия исходного shopConfig. */
    getShopItemData(id: string): IShopItemData {
        return getShopItemData(this.props.shopConfig, id);
    }

    /** Собирает данные витрины магазина в порядке конфига и только с доступными API in-app товарами. */
    getBonusShopData(): BonusShopViewData {
        const {shopConfig} = this.props;
        const rewardId = this.getRewardPurchaseId();
        const reward = this.isRewardEnabled() && rewardId != null && this.isRewardPurchaseId(rewardId)
            ? {
                id: rewardId,
                consumables: this.getShopItemData(rewardId).consumables,
            }
            : undefined;

        const shopItems = shopConfig.shopItemsOrdered.buyItemIds
            .map((id) => this.mapApiShopItemToViewData(id))
            .filter((item): item is BonusShopBuyViewData => item != null);

        return {
            reward,
            shopItems,
        };
    }

    /** Алиас для мест, где удобнее читать метод как подготовку данных view. */
    getShopViewData(): BonusShopViewData {
        return this.getBonusShopData();
    }

    /** заказываем покупку **/
    async purchaseInApp(id: string): Promise<ShopPurchaseResult> {
        if (this.apiService == null) return {error: "shop not available"};
        return this.apiService.shopPurchase(id, (purchase) => this.activatePurchaseOnBalance(purchase));
    }

    /** Явно активирует покупки, которые Yandex вернул как не consume-нутые. */
    async activatePendingPurchases(): Promise<void> {
        await this.apiService?.activatePendingPurchases((purchase) => this.activatePurchaseOnBalance(purchase));
    }

    /** заказываем рекламу напрямую **/
    async purchaseReward(id: string): Promise<ShopPurchaseResult> {
        const adResult = await this.props.showRewardedAd();
        if (!adResult.isReward) {
            return {error: adResult.error ?? "reward ad not completed", purchaseId: id};
        }

        try {
            await this.saveShopItemOnBalance(id);
        } catch (e) {
            return {error: getErrorMessage(e), purchaseId: id};
        }

        return {purchaseId: id};
    }

    /************
     * PRIVATE
     **********/

    /** предварительная загрузка и инициализация **/
    private async initApi(): Promise<void> {
        if (this.apiService != null) return;
        if (isMockShopEnabled() || this.props.isMockShop) {
            const availablePurchaseIds = this.props.shopConfig.shopItemsOrdered.buyItemIds.map(item => item);

            this.apiService = new MockInAppService({
                availablePurchaseIds,
            });
        } else {
            const {sdk} = this.props;
            if (sdk == null) return;
            this.apiService = new YandexInAppService({
                sdk,
            });
        }

        try {
            await this.apiService.preload();
        } catch (e) {
            console.warn("apiService preload failed", e);
        }
    }

    /** Активирует in-app покупку в балансе игрока до consumePurchase. */
    private async activatePurchaseOnBalance(purchase: IInAppPurchase): Promise<void> {
        await this.saveShopItemOnBalance(purchase.productID);
    }

    /** Превращает id магазина в новый баланс игрока. */
    private async saveShopItemOnBalance(shopItemId: string): Promise<void> {
        const {playerDataService} = this.props;
        const currentPlayerData = playerDataService.get();
        const nextPlayerData = this.mapShopItemToPlayerData(shopItemId, currentPlayerData);
        playerDataService.set(nextPlayerData);
        await playerDataService.flush();
    }

    /** Преобразует configured in-app товар в данные карточки, если товар пришел из API. */
    private mapApiShopItemToViewData(id: string): BonusShopBuyViewData | undefined {
        if (!this.isInAppPurchaseId(id)) {
            return;
        }

        const apiShopItem = this.getApiShopItemById(id);
        if (!apiShopItem) {
            return;
        }

        return {
            id,
            consumables: this.getShopItemData(id).consumables,
            priceString: `${apiShopItem.price} ${apiShopItem.currency}`,
        };
    }

    /** Применяет покупку к данным игрока через общий shop reducer. */
    private mapShopItemToPlayerData(shopItemId: string, prevPlayerData: GamePlayerData): GamePlayerData {
        return this.props.addShopItemToState({
            shopConfig: this.props.shopConfig,
            shopItemId,
            prevPlayerData,
        });
    }
}
