import {Align, makeAlign} from "@kvisaz/phaser-sugar";
import {getSceneLocale, onSceneLocaleChange} from "../../common";
import {ConsumableType} from "../../logic";
import type {IAutoTextChildData, IAutoViewAssetChildData} from "../auto_generated/types";
import {buttonShopItemData} from "../auto_generated/assets-views.view";
import {ButtonEvents} from "../auto_generated/utils/addButtonViewInteractivity";
import {BonusShopItemData, BonusShopItemType} from "./types";
import {ViewElementBuilder} from "../../assets";

interface IBonusShopItemProps {
    scene: Phaser.Scene;
    item: BonusShopItemData;
    itemType: BonusShopItemType;
}

const BONUS_ICON_KEYS = [
    ConsumableType.UNDO,
    ConsumableType.HINT,
    ConsumableType.MAGIC,
] as const;

const ACTION_BUTTON_BOTTOM_IN = 10;

const BONUS_ICON_DATA_BY_TYPE = {
    [ConsumableType.UNDO]: buttonShopItemData.children.iconButtonUndo,
    [ConsumableType.HINT]: buttonShopItemData.children.iconButtonHint,
    [ConsumableType.MAGIC]: buttonShopItemData.children.iconButtonMagic,
};

const BONUS_TEXT_DATA_BY_TYPE = {
    [ConsumableType.UNDO]: buttonShopItemData.children.textUndoValue,
    [ConsumableType.HINT]: buttonShopItemData.children.textValueHint,
    [ConsumableType.MAGIC]: buttonShopItemData.children.textValueMagic,
};

/** ToDo - отказать от автогенерации все перевести на ViewElementBuilder!
 *  ассеты - вручную* Карточка пакета бонусов из generated buttonShopItemData. */
export class BonusShopItem extends Phaser.GameObjects.Container {
    /** Создает карточку магазина с отдельной нижней кнопкой. */
    constructor(private readonly props: IBonusShopItemProps) {
        super(props.scene, 0, 0);
        const {scene} = props;
        const isReward = props.itemType === "reward";
        this.name = "BonusShopItem";
        this.setSize(buttonShopItemData.width, buttonShopItemData.height);
        const builder = new ViewElementBuilder(scene);
        const bg = this.createAsset(buttonShopItemData.children["bgGoldShopItem.nine.40"]);
        const actionButton = isReward
            ? builder.shopItemRewardButton(() => this.emitButtonClick())
            : builder.shopItemBuyButton(props.item.priceString ?? "", () => this.emitButtonClick());

        actionButton.name = "BonusShopItemButton";
        actionButton.setData("bonusShopItemId", props.item.id);
        actionButton.setData("bonusShopItemType", props.itemType);

        this.add([
            bg,
            ...this.createBonuses(),
            actionButton,
        ]);
        makeAlign((align) => {
            align.anchor(bg).centerX(actionButton).bottomIn(actionButton, -ACTION_BUTTON_BOTTOM_IN);
        });
    }

    /** Создает три строки бонусов: undo, hint, magic. */
    private createBonuses(): Phaser.GameObjects.GameObject[] {
        return BONUS_ICON_KEYS.flatMap((type) => {
            const icon = this.createAsset(BONUS_ICON_DATA_BY_TYPE[type]);
            const text = this.createText(BONUS_TEXT_DATA_BY_TYPE[type], String(this.props.item.consumables[type]));

            /** Число бонусов сохраняет generated Y и стоит справа от иконки с отступом 10. */
            makeAlign((align) => {
                align.anchor(icon).rightTo(text, 10).centerY(text);
            });

            return [icon, text];
        });
    }

    /** Отправляет событие клика магазина с id конкретного пакета бонусов. */
    private emitButtonClick(): void {
        this.scene.events.emit(ButtonEvents.onClick, {
            gameObjectName: "BonusShopItemButton",
            bonusShopItemId: this.props.item.id,
            bonusShopItemType: this.props.itemType,
        });
    }

    /** Создает asset child с координатами из generated buttonShopItemData. */
    private createAsset(data: IAutoViewAssetChildData): Phaser.GameObjects.Image | Phaser.GameObjects.NineSlice {
        const asset = data.asset.kind === "nine"
            ? new Phaser.GameObjects.NineSlice(
                this.scene,
                0,
                0,
                data.asset.url,
                data.asset.frameName,
                data.width,
                data.height,
                data.asset.ninePadding ?? 20,
                data.asset.ninePadding ?? 20,
                data.asset.ninePadding ?? 20,
                data.asset.ninePadding ?? 20,
            )
            : new Phaser.GameObjects.Image(this.scene, 0, 0, data.asset.url, data.asset.frameName);

        asset.name = data.asset.name || "";
        Align.setLeftTop(
            asset,
            data.x - buttonShopItemData.width / 2,
            data.y - buttonShopItemData.height / 2,
        );

        return asset;
    }

    /** Создает text child с координатами из generated buttonShopItemData. */
    private createText(data: IAutoTextChildData, value?: string): Phaser.GameObjects.Text {
        const locale = getSceneLocale(this.scene) ?? "ru";
        const text = new Phaser.GameObjects.Text(
            this.scene,
            0,
            0,
            value ?? data.text.localeMap[locale] ?? data.text.localeMap.ru,
            data.text.style,
        );

        text.name = data.text.name || "";
        text.setOrigin(0, 0);
        Align.setLeftTop(
            text,
            data.x - buttonShopItemData.width / 2,
            data.y - buttonShopItemData.height / 2,
        );

        if (value == null) {
            const unsubscribeLocale = onSceneLocaleChange(this.scene, (nextLocale) => {
                text.setText(data.text.localeMap[nextLocale] ?? "");
            });
            text.once(Phaser.GameObjects.Events.DESTROY, unsubscribeLocale);
        }

        return text;
    }
}
